def copy(src,dst):
 dst=Path(dst);dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dst)

def graphml(graph,path):
 ns='http://graphml.graphdrawing.org/xmlns';ET.register_namespace('',ns);root=ET.Element('{'+ns+'}graphml')
 for k,domain,typ in [('label','node','string'),('node_type','node','string'),('relation_type','edge','string'),('weight','edge','double'),('sign','edge','string')]:ET.SubElement(root,'{'+ns+'}key',id=k,attrib={'for':domain,'attr.name':k,'attr.type':typ})
 gg=ET.SubElement(root,'{'+ns+'}graph',id='AMG_v2',edgedefault='directed')
 for n in graph['nodes']:
  e=ET.SubElement(gg,'{'+ns+'}node',id=n['id'])
  for k,v in [('label',n.get('canonical_name',n['id'])),('node_type',n['node_type'])]:ET.SubElement(e,'{'+ns+'}data',key=k).text=str(v)
 for i,r in enumerate(graph['edges']):
  e=ET.SubElement(gg,'{'+ns+'}edge',id=r.get('edge_id',str(i)),source=r['source_id'],target=r['target_id'])
  for k in ['relation_type','weight','sign']:
   if k in r:ET.SubElement(e,'{'+ns+'}data',key=k).text=str(r[k])
 ET.ElementTree(root).write(path,encoding='utf-8',xml_declaration=True)

def viewer(graph,path):
 data=json.dumps(graph,ensure_ascii=False,separators=(',',':')).replace('<','\u003c')
 html='<!doctype html><html lang="zh"><meta charset="utf-8"><title>AMG v2 图检查器</title><style>body{margin:0;background:#111827;color:#e5e7eb;font:14px system-ui}header{padding:18px 24px;background:#172033}h1{margin:0 0 10px;font-size:22px}input{padding:8px 12px;width:270px;border:1px solid #4b5563;border-radius:6px;background:#111827;color:white}label{margin-left:16px}main{display:grid;grid-template-columns:1fr 340px;height:calc(100vh - 132px)}canvas{width:100%;height:100%;touch-action:none}aside{border-left:1px solid #374151;padding:18px;overflow:auto}pre{font:12px/1.6 ui-monospace;white-space:pre-wrap;overflow-wrap:anywhere}.muted{color:#9ca3af;margin:9px 0 0;font-size:12px}</style><header><h1>AMG v2 · 复用原 Cue Student</h1><input id="search" placeholder="搜索 Cue、Appraisal 或情绪名称"><label><input type="checkbox" id="isolated" style="width:auto">显示孤立节点</label><span id="counts" style="margin-left:18px"></span><p class="muted">滚轮缩放 · 拖动平移 · 点击查看节点及准入关系。条件预测关联；内部源域实验，非 OOF。AE 未通过增量门控时保留参数并隐藏推理路径。</p></header><main><canvas id="canvas"></canvas><aside><b>节点与关系审计</b><pre id="detail">点击节点查看详情。</pre></aside></main><script>const G=__GRAPH__;const cv=document.getElementById(\'canvas\'),ctx=cv.getContext(\'2d\'),detail=document.getElementById(\'detail\');let scale=1,dx=0,dy=0,drag=null,visible=[],positions=new Map();const colors={CueType:\'#60a5fa\',AppraisalDimension:\'#c084fc\',AppraisalState:\'#fbbf24\',EmotionConcept:\'#34d399\'};const incident=new Set(G.edges.flatMap(e=>[e.source_id,e.target_id]));function setup(){const rect=cv.getBoundingClientRect();cv.width=rect.width*devicePixelRatio;cv.height=rect.height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);draw()}function filtered(){const query=document.getElementById(\'search\').value.toLowerCase().trim(),isolated=document.getElementById(\'isolated\').checked;let nodes=G.nodes.filter(n=>isolated||incident.has(n.id));if(query){const hit=new Set(G.nodes.filter(n=>(n.id+\' \'+(n.canonical_name||\'\')).toLowerCase().includes(query)).map(n=>n.id));for(const e of G.edges)if(hit.has(e.source_id)||hit.has(e.target_id)){hit.add(e.source_id);hit.add(e.target_id)}nodes=G.nodes.filter(n=>hit.has(n.id))}return nodes}function draw(){const w=cv.clientWidth,h=cv.clientHeight;ctx.clearRect(0,0,w,h);visible=filtered();positions.clear();const types=[\'CueType\',\'AppraisalDimension\',\'AppraisalState\',\'EmotionConcept\'];types.forEach((type,col)=>{const nodes=visible.filter(n=>n.node_type===type);nodes.forEach((n,i)=>positions.set(n.id,{x:85+col*Math.max(160,(w-180)/3),y:55+(i+.5)*Math.max(14,(h-100)/Math.max(1,nodes.length))}))});ctx.save();ctx.translate(dx,dy);ctx.scale(scale,scale);for(const e of G.edges){const a=positions.get(e.source_id),b=positions.get(e.target_id);if(!a||!b)continue;ctx.strokeStyle=e.sign===\'negative\'?\'#ef444444\':\'#64748b55\';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}for(const n of visible){const p=positions.get(n.id);ctx.fillStyle=colors[n.node_type];ctx.beginPath();ctx.arc(p.x,p.y,4,0,7);ctx.fill();ctx.font=\'10px system-ui\';ctx.fillStyle=\'#d1d5db\';ctx.fillText(n.canonical_name||n.id,p.x+7,p.y+3)}ctx.restore();document.getElementById(\'counts\').textContent=visible.length+\' / \'+G.nodes.length+\' 节点 · \'+G.edges.filter(e=>e.relation_type!==\'HAS_STATE\').length+\' 条准入学习边\'}cv.onwheel=e=>{e.preventDefault();const r=cv.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,k=e.deltaY<0?1.15:1/1.15;dx=x-(x-dx)*k;dy=y-(y-dy)*k;scale*=k;draw()};cv.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,ox:dx,oy:dy};cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(drag){dx=drag.ox+e.clientX-drag.x;dy=drag.oy+e.clientY-drag.y;draw()}};cv.onpointerup=e=>{const moved=drag&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>4;drag=null;if(moved)return;const r=cv.getBoundingClientRect(),x=(e.clientX-r.left-dx)/scale,y=(e.clientY-r.top-dy)/scale;const n=visible.find(n=>{const p=positions.get(n.id);return Math.hypot(x-p.x,y-p.y)<10/scale});if(n)detail.textContent=JSON.stringify({node:n,relations:G.edges.filter(e=>e.source_id===n.id||e.target_id===n.id)},null,2)};document.getElementById(\'search\').oninput=()=>{dx=dy=0;scale=1;draw()};document.getElementById(\'isolated\').onchange=draw;window.onresize=setup;setup();</script></html>'
 path.write_text(html.replace('__GRAPH__',data))

def main():
 complete=read(ROOT/'work/fit_complete.json');assert complete['complete'];info=read(ROOT/'data/prepared.json');config=read(ROOT/'config.json');binding=read(ROOT/'data/student_binding.json');cal=read(ROOT/'work/calibration.json');comparison=read(ROOT/'work/method_comparison.json');admitted=read(ROOT/'work/admitted_edges.json');schema=read(ROOT/'schema.json')
 for method in ['G1','G2','G3']:
  rr=read(ROOT/f'work/{method}_fit.json');assert all(a['converged'] for k in ['CA','CE','AE'] for a in rr[k]),method+' has non-converged relations'
 rid='amg_v2_reuse_'+digest(dict(plan=info['source_plan_sha256'],config=sha(ROOT/'config.json'),model=sha(ROOT/'work/G1.npz'),edges=sha(ROOT/'work/edge_audit.csv'),calibration=sha(ROOT/'work/calibration.json'),runtime=sha(ROOT/'runtime.py')))[:16]
