 write(release/'ontology/cue_nodes.json',cn)
 emo=read(release/'ontology/emotion_nodes.json');incoming=collections.Counter(e['target_id'] for typ in ['CE','AE'] for e in admitted[typ])
 for n in emo:n.update(has_valid_incoming_edge=bool(incoming[n['id']]),graph_predictable=bool(incoming[n['id']]),edge_status='admitted_incoming' if incoming[n['id']] else 'isolated_concept_retained')
 write(release/'ontology/emotion_nodes.json',emo)
 nodes=cn+read(release/'ontology/appraisal_dimensions.json')+read(release/'ontology/appraisal_states.json')+emo;assert len(nodes)==252 and len({n['id'] for n in nodes})==252
 taxonomy=[dict(edge_id='HAS_STATE_'+n['id'],source_id=n['dimension_id'],target_id=n['id'],relation_type='HAS_STATE') for n in read(release/'ontology/appraisal_states.json')]
 graph=dict(schema_version='amg_global_graph_v2',release_id=rid,nodes=nodes,edges=taxonomy+sum(admitted.values(),[]),matrix_parameters='learned_relations/G1.npz',edge_semantics='signed_conditional_predictive_association',student_retrained=False,cue_scores_oof=False,path_branch_enabled=cal['path_branch_enabled'],training_scope='Source-domain only; user requested frozen existing Cue Student')
 write(release/'graph.json',graph);graphml(graph,release/'graph.graphml');viewer(graph,release/'graph_viewer.html')
 for method in ['G1','G2','G3']:copy(ROOT/f'work/{method}.npz',release/f'learned_relations/{method}.npz');copy(ROOT/f'work/{method}_fit.json',release/f'validation/{method}_fit.json')
 for name in ['edge_audit.csv','admitted_edges.json','npmi_baseline.npz']:copy(ROOT/'work'/name,release/'learned_relations'/name)
 copy(ROOT/'work/calibration.json',release/'calibration/relation_calibration.json');copy(ROOT/'work/cue_policy.json',release/'calibration/cue_policy.json');copy(ROOT/'work/paths.json',release/'paths/path_audit.json');copy(ROOT/'data/student_binding.json',release/'runtime/student_binding.json');copy(ROOT/'schema.json',release/'runtime/schema.json');copy(ROOT/'config.json',release/'config.json')
 for name in ['method_comparison.json','bootstrap_report.json','fit_complete.json']:copy(ROOT/'work'/name,release/'validation'/name)
 for f in (ROOT/'work').glob('relation_fold*'):copy(f,release/'validation/relation_folds'/f.name)
 for f in (ROOT/'work/bootstrap').glob('*.npz'):copy(f,release/'validation/bootstrap_relations'/f.name)
 for name in ['prepared.json','split_manifest.json','label_manifest.json','exposure_ledger.csv','cache_verification.json','cache_inventory.jsonl']:copy(ROOT/'data'/name,release/'data'/name)
 for f in (ROOT/'source_snapshot').iterdir():copy(f,release/'source_snapshot'/f.name)
 for f in ROOT.glob('*.py'):copy(f,release/'source_snapshot/code'/f.name)
 z=np.load(ROOT/'data/labels.npz');pred=np.load(ROOT/'work/predictions.npz');cuepolicy=read(ROOT/'work/cue_policy.json');tune=z['tune'];cue_counts=(pred['cue_calibrated'][tune]>=np.array(cuepolicy['thresholds'])).sum(1);branch=cal['branches']['fusion'] if cal['path_branch_enabled'] else cal['branches']['CE'];ep=pred['fused'] if cal['path_branch_enabled'] else pred['CE'];emo_counts=(ep[tune]>=np.array(branch['thresholds'])).sum(1)
 prompt_policy=dict(cue_top_k=int(np.clip(np.ceil(np.quantile(cue_counts,.75)),1,12)),emotion_top_k=int(np.clip(np.ceil(np.quantile(emo_counts,.9)),1,8)),selection='Cue: tuning-set activated-count 75th percentile; Emotion: tuning-set thresholded-count 90th percentile; pre-specified quantile rules; not selected on targets',status='engineering_only_downstream_prompt_validation_not_run')
 write(release/'runtime/prompt_policy.json',prompt_policy)
 import sklearn,scipy
 manifest=dict(release_id=rid,status='assembling',created_at=datetime.now(ZoneInfo('Asia/Shanghai')).isoformat(),source_plan_sha256=info['source_plan_sha256'],student_retrained=False,cue_oof=False,strict_document_P0_complete=False,user_scope_override=info['user_scope_override'],node_counts=dict(CueType=42,AppraisalDimension=6,AppraisalState=16,EmotionConcept=188),learned_edge_counts=complete['edge_admitted_counts'],taxonomy_edges=16,path_branch_enabled=cal['path_branch_enabled'],independent_confirmation=False,target_datasets_used=False,affectgpt_retrained=False,python=sys.version,dependencies=dict(numpy=np.__version__,scipy=scipy.__version__,sklearn=sklearn.__version__),code_hashes={f.name:sha(f) for f in ROOT.glob('*.py')},limitations=[info['validation_limitation'],info['group_limitations'],'Bootstrap intervals condition on frozen Student scores and cross-fitted Appraisal inputs; they are not end-to-end pipeline uncertainty.','No new AffectGPT integration/training or nine-target evaluation.'])
 write(release/'release_manifest.json',manifest)
 engine=SampleGraph(release);sampledir=release/'runtime/examples';sampledir.mkdir(parents=True,exist_ok=True);empty=engine.build('empty_example',[None]*42);write(sampledir/'empty_fallback.json',empty);cache=Path(binding['source_cache']);ids=z['sample_ids'];stats=collections.Counter();nodecounts=[];edgecounts=[];patterns=collections.Counter();representatives=set();available_counts=collections.Counter();schema_validator=__import__('jsonschema').Draft202012Validator(schema)
 with (release/'runtime/internal_evaluation_sample_graphs.jsonl').open('w') as out:
  for i in np.flatnonzero(z['evaluation']):
   rec=read(cache/(str(ids[i])+'.json'));g=engine.build_from_old_cue(rec['cue']);schema_validator.validate(g);out.write(json.dumps(g,ensure_ascii=False,separators=(',',':'))+'\n');cov=g['coverage'];stats['samples']+=1;stats['fallback']+=int(g['fallback']['required']);stats['unresolved_dimensions']+=cov['appraisal_unresolved_dimensions'];nodecounts.append(len(g['nodes']));edgecounts.append(len(g['edges']));pattern='empty' if not cov['cue_count'] else 'full' if cov['appraisal_supported_count'] and cov['emotion_candidate_count'] else 'cue_appraisal' if cov['appraisal_supported_count'] else 'cue_emotion' if cov['emotion_candidate_count'] else 'cue_only';patterns[pattern]+=1
   if pattern not in representatives:write(sampledir/(pattern+'.json'),g);representatives.add(pattern)
   for m,v in cov['available_modalities'].items():available_counts[m]+=int(v)
 stats=dict(stats,mean_node_count=float(np.mean(nodecounts)),mean_edge_count=float(np.mean(edgecounts)),patterns=dict(patterns),fallback_ratio=stats['fallback']/stats['samples'],unresolved_dimension_ratio=stats['unresolved_dimensions']/(6*stats['samples']),available_modality_samples=dict(available_counts));write(release/'validation/sample_graph_metrics.json',stats)
 from .verify import verify
 acceptance=verify(release);assert acceptance['passed']
 # Verify deployed inference assets stayed identical without loading or retraining models.
 from graph_paths import resolve_path
 assets=[]
 for m,spec in binding['exports'].items():
  actual=Path(resolve_path(spec['path']));actual_sha=sha(actual);assert actual_sha==spec['sha256'];assets.append(dict(modality=m,path=str(actual),sha256=actual_sha,unchanged=True))
 write(release/'validation/student_unchanged.json',dict(passed=True,assets=assets,retrained=False))
 lines=['# AMG v2：复用原 Cue 提取器的图重构结果','',f"Release：`{rid}`",'',f"本体 252 个节点；准入学习边 {sum(complete['edge_admitted_counts'].values())} 条（CA {complete['edge_admitted_counts']['CA']}、CE {complete['edge_admitted_counts']['CE']}、AE {complete['edge_admitted_counts']['AE']}）；另有 16 条 HAS_STATE 固定归属边。",'', '## 范围与实现','', '按用户要求固定并复用原 Text / Audio / Visual Cue Student，以及已有的 30,755 条源域预测缓存。未训练 Cue 提取器，未训练 AffectGPT，未使用九个目标集。旧图、旧模型和旧运行目录保持原样。','', '与文档的明确差异：未重新生成 Student 五折 OOF。27,679 条关系训练样本使用旧 Student 的训练内预测；1,538 条用于内部校准和门槛选择，另外 1,538 条用于冻结后的内部关系评估。这些历史验证样本曾参与 Student 选模和 AffectGPT 续训，因此不是全新独立确认集。300 条人工审计与 200 条保留数据未用于本次构建。','', 'CA 为六维独立 Softmax，逐维 Appraisal Mask。AE 使用关系模型交叉拟合的 Appraisal 预测概率训练，未使用 Teacher one-hot 作为输入。CE / AE 为带 Emotion Mask 的多标签 Logistic。完整映射且非空的源标签集合按冻结协议允许闭世界负例；丢词、OOV、部分映射仅保留已知正例，其他位置屏蔽。','', '保留 NPMI、纯学习 G1、NPMI 弱先验 G2、稀疏有符号 G3 对照；五折符号稳定性；64 次按已知来源组重采样的 CA / CE / AE 重新拟合；边删除 Brier 增量；逐 Cue 校准、逐维 unresolved、Emotion 门控和 fallback。','', '## 内部源域结果','', '|方法|CE Macro AP|CE Brier|CE+AE Macro AP|两跳准入|','|---|---:|---:|---:|---|']
 for name,v in comparison.items():lines.append(f"|{name}|{v['internal_evaluation']['CE']['macro_ap']:.6f}|{v['internal_evaluation']['CE']['brier']:.6f}|{v['fusion_internal_evaluation']['macro_ap']:.6f}|{v['path_branch_enabled']}|")
 lines+=['', '主方案固定 G1。其融合系数由内部校准材料选择；当前最优 alpha=0，因此未发现可启用的 AE 增量。AE 参数和所有 3,008 条候选关系仍保留在审计表中，正式证据图不强行补 AE 边或两跳路径。','',f"内部评估样本图 {stats['samples']} 份，平均 {stats['mean_node_count']:.2f} 个实例节点、{stats['mean_edge_count']:.2f} 条边（含 INSTANCE_OF）；fallback {stats['fallback_ratio']:.2%}。类型分布：`{json.dumps(stats['patterns'],ensure_ascii=False)}`。",'',f"验收通过 {len(acceptance['checks'])} 项关键检查，包括集合/组隔离、Mask、Appraisal cross-fit 独立复算、CE 标量复算、不可用与负例区别、deferred / not_requested、互斥状态、Schema、Cue 顺序、回退与极性/开放词汇保护。",'', '## 文件与使用','', '- `graph.json` / `graph.graphml`：全局本体和准入关系。','- `graph_viewer.html`：离线图检查器；搜索、缩放、点击查看关系审计。','- `learned_relations/G1.npz`：CA / AE / CE 全部参数及 bias；未准入系数仍可审计。','- `learned_relations/edge_audit.csv`：11,576 条候选边的支持量、符号、Bootstrap 区间、删除增量和准入原因。','- `runtime/internal_evaluation_sample_graphs.jsonl`：1,538 份实际样本子图。','- `runtime/examples/`：实际样本类型示例和空图回退示例。','- `validation/`：方法对照、Bootstrap、逐类指标、样本图统计和验收报告。','- `data/`：分组、数据曝光、缓存身份与标签掩码清单。','', '```python','from amg_graph_v2.runtime import SampleGraph, prompt_evidence',f"engine = SampleGraph({str(release)!r})","sample_graph = engine.build_from_old_cue(old_cue_output)","# old_cue_output 由未改动的原 StudentRunner 生成；无需重训或换模型。","# 仅在需要源域工程检查时查看；尚未做新的下游验证。","text = prompt_evidence(sample_graph, task='open_vocabulary')",'```','', '保留边的负号只表示模型条件贡献方向，不代表心理因果或反证。分数校准仅来自历史内部开发材料。本 release 是完成验收的图重构工程版本，不宣称满足原方案严格 Student OOF P0，也不宣称提升 AffectGPT 下游成绩。']
 (release/'REPORT.md').write_text('\n'.join(lines)+'\n')
 manifest.update(status='verified_internal_engineering_release',acceptance_passed=True,sample_graph_count=stats['samples'],artifact_sha256={str(f.relative_to(release)):sha(f) for f in sorted(release.rglob('*')) if f.is_file() and f.name!='release_manifest.json'});write(release/'release_manifest.json',manifest)
 # Final immutable-file digest round trip.
 for name,expected in manifest['artifact_sha256'].items():assert sha(release/name)==expected
 write(ROOT/'current.json',dict(path=str(release),release_id=rid,report=str(release/'REPORT.md'),graph=str(release/'graph.json'),viewer=str(release/'graph_viewer.html'),status=manifest['status'],student_retrained=False,cue_oof=False))
 (ROOT/'README.md').write_text('# AMG v2 图重构（复用原 Cue Student）\n\n当前发布入口：`current.json`。仅在服务器目录内工作。旧图和旧 Cue 提取器没有修改。\n\n数据准备 `prepare.py`；旧 Student 缓存身份核验 `reuse_cues.py`；关系学习与审计 `fit.py`；样本图运行时 `runtime.py`；冻结导出 `release.py`；验收 `verify.py`。\n\nCue Student 保持原发布，未重训、未重新生成 OOF。新建五折仅用于图关系 cross-fitting 和边稳定性。详细差异、源域曝光和准入门槛见发布 REPORT.md。\n\n复现从项目 graph 目录使用 `/ai/sjq/miniconda3/envs/vllm/bin/python -B -m amg_graph_v2...`。冻结发布不可覆盖。临时冻结预训练编码器特征分支在确定用户范围后已停止，未训练预测头，也不参与最终图。\n')
 event('release_verified',path=str(release),release_id=rid,nodes=252,learned_edges=sum(complete['edge_admitted_counts'].values()),sample_graphs=stats['samples'],checks=len(acceptance['checks']))
